// C# 6.4.3: escapes use the same Unicode categories as literal identifier characters.
// Generate compact fixed-width hexadecimal alternatives with the pinned Node Unicode data.
function identifierCharacter(categories) {
  const literal = new RegExp(`[${categories}]`, 'u');
  const ranges = [];
  for (let c = 0; c <= 0x10FFFF; c++) {
    if (!literal.test(String.fromCodePoint(c))) continue;
    const last = ranges[ranges.length - 1];
    if (last && last[1] === c - 1) last[1] = c;
    else ranges.push([c, c]);
  }
  function hexPattern(low, digits, subset) {
    const high = low + 16 ** digits - 1;
    subset = subset.filter(([a, b]) => a <= high && b >= low);
    if (!subset.length) return null;
    if (subset[0][0] <= low && subset[0][1] >= high)
      return digits ? `[0-9A-Fa-f]{${digits}}` : '';
    const groups = new Map();
    for (let digit = 0; digit < 16; digit++) {
      const suffix = hexPattern(low + digit * 16 ** (digits - 1), digits - 1, subset);
      if (suffix === null) continue;
      const chars = digit.toString(16);
      const previous = groups.get(suffix) || '';
      groups.set(suffix, previous + chars + (digit >= 10 ? chars.toUpperCase() : ''));
    }
    const alternatives = [...groups].map(([suffix, chars]) =>
      (chars.length === 1 ? chars : `[${chars}]`) + suffix);
    return alternatives.length === 1 ? alternatives[0] : `(${alternatives.join('|')})`;
  }
  // Use these same ranges for literals: the generator's Unicode table may differ.
  const characters = ranges.map(([a, b]) => `\\u{${a.toString(16)}}` +
    (a === b ? '' : `-\\u{${b.toString(16)}}`)).join('');
  return new RegExp(`([${characters}]|\\\\u${hexPattern(0, 4, ranges)}|\\\\U${hexPattern(0, 8, ranges)})`, 'u');
}

