static inline bool is_pp_new_line(int32_t c) {
    return c == '\n' || c == '\r' || c == 0x85 || c == 0x2028 || c == 0x2029;
}

static inline bool is_pp_space(int32_t c) {
    return c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == 0xA0 || c == 0xFEFF || c == 0x1680 ||
           (c >= 0x2000 && c <= 0x200A) || c == 0x202F || c == 0x205F || c == 0x3000;
}

// ECMA-334 6.5.5: the grammar selects the first section whose condition is not
// the literal false (or !true); every other section is skipped. A skipped section is not
// lexically processed except for directives, which only matter for finding
// the #elif / #else / #endif that ends the section (nested #if..#endif groups
// are skipped whole). The token covers the section from its first to its last
// non-white-space character; white space around it stays extras.
static bool scan_preproc_skipped_section(TSLexer *lexer) {
    if (lexer->get_column(lexer) != 0) {
        // Rest of the #else line: white space and an optional single-line
        // comment, which the grammar lexes before calling here again.
        while (is_pp_space(lexer->lookahead)) {
            skip(lexer);
        }
        if (!lexer->eof(lexer) && !is_pp_new_line(lexer->lookahead)) {
            return false;
        }
    }
    bool has_content = false;
    unsigned depth = 0;
    for (;;) {
        while (!lexer->eof(lexer) && (is_pp_new_line(lexer->lookahead) || is_pp_space(lexer->lookahead))) {
            lexer->advance(lexer, !has_content);
        }
        if (lexer->eof(lexer)) {
            break;
        }
        if (lexer->lookahead == '#') {
            advance(lexer);
            while (is_pp_space(lexer->lookahead)) {
                advance(lexer);
            }
            char name[6];
            size_t n = consume_identifier_into(lexer, name, sizeof(name));
            if (buf_equals(name, n, "if")) {
                depth++;
            } else if (buf_equals(name, n, "endif") || buf_equals(name, n, "elif") || buf_equals(name, n, "else")) {
                if (depth == 0) {
                    break;
                }
                if (name[1] == 'n') {
                    depth--;
                }
            }
            lexer->mark_end(lexer);
            has_content = true;
        }
        while (!lexer->eof(lexer) && !is_pp_new_line(lexer->lookahead)) {
            bool space = is_pp_space(lexer->lookahead);
            advance(lexer);
            if (!space) {
                lexer->mark_end(lexer);
                has_content = true;
            }
        }
    }
    lexer->result_symbol = PREPROC_SKIPPED_SECTION;
    return has_content;
}

bool tree_sitter_c_sharp_external_scanner_scan(void *payload, TSLexer *lexer, const bool *valid_symbols) {
    Scanner *scanner = (Scanner *)payload;

    // Valid only right after an #else line or the condition line of a skipped
